type Config struct{ Port int }

func NewServer(addr string, cfg Config) *Server {
	if cfg.Port == 0 {
		cfg.Port = 8080
	}
	return &Server{addr: addr, port: cfg.Port}
}

func main() {
	// the caller wants a random free port
	s := NewServer("127.0.0.1", Config{Port: 0})
	fmt.Println("port:", s.port)
}
